  ppOwnerNote(pid);
  wsSafeSend(JSON.stringify({ v: 1, type: "profile.get", projectId: pid }));
  wsSafeSend(JSON.stringify({ v: 1, type: "profile.file", projectId: pid })); // 文件清单(step-048 追记八)
