// ── 内置浏览器 ──
function isHttpUrl(u) { return u.indexOf("http://") === 0 || u.indexOf("https://") === 0; }
function brGo() {
  let u = $("brUrl").value.trim();
  if (!u) return;
  if (!isHttpUrl(u)) u = "https://" + u;
  $("brUrl").value = u;
  $("brFrame").src = u;
}
$("brGo").onclick = brGo;
$("brUrl").onkeydown = (e) => { if (e.key === "Enter") brGo(); };
