    const flt = cvSvgFilterOf();
    const body = { v: 1, type: "board.diagram", sessionId: currentSid, taskId: (doc && doc.taskId) || boardTaskId || "", theme: light ? "light" : "dark" };
    if (flt) body.filter = flt; // 无过滤时请求体不带 filter 字段(保持既有请求形态)
