    for (const id of auto) if (!seen.has(id)) level.set(id, 0);
    const byLevel = new Map();
    for (const id of auto) { const l = level.get(id) || 0; if (!byLevel.has(l)) byLevel.set(l, []); byLevel.get(l).push(id); }
