  const stages = (s.stages || []).map((st) =>
    '<span class="cv-type-stage' + (st.missing ? " missing" : "") + '" title="' + esc(st.hint || "") + '">' +
    '<b style="color:' + (st.missing ? "var(--bcv-wire-foot-fg,#8f8068)" : p.color) + '">' + st.count + "</b>" + esc(st.label) + (st.missing ? " 缺" : "") + "</span>").join("");
