      boardSelNode = el.dataset.cv;
      if (!boardEditOn) boardEditToggle(); // 进入编辑态(内部 renderBoard 重渲,选中态由 selCls 承载)
      else {
        renderBoardDetail();
        for (const x of host.querySelectorAll(".cv-node")) x.classList.toggle("on", x.dataset.cv === boardSelNode);
      }
