$("voiceBtn").onclick = function () {
  if (!voiceSupported()) { toast("当前环境不支持录音(缺 MediaRecorder 或麦克风权限)", 1); return; }
  if (voiceRec) { voiceRecStop(); return; }
  if (voiceLocked(currentSid)) { toast("本会话任务书撰写中,请稍候…"); return; }
  voiceRecStart();
};
