    const r = scroll.getBoundingClientRect();
    const cur = parseFloat(el.dataset.scale || "0") || 1;
    const bw = Math.max(1, scroll.clientWidth - 32), bh = Math.max(1, scroll.clientHeight - 32);
    const fit = Math.min(1, bw / n.w, bh / n.h);
